package io.invenlio.inventory;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.organization.*;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.time.Instant;import java.util.*;import org.slf4j.MDC;import org.springframework.context.ApplicationEventPublisher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service class InventoryService implements InventoryOnHandQuery{
 private final AuthorizationService auth;private final AuditTrail audit;private final CatalogInventoryLookup catalog;private final WarehouseAvailability warehouse;private final JdbcTemplate jdbc;private final ApplicationEventPublisher events;private final TraceabilityService trace;
 InventoryService(AuthorizationService a,AuditTrail au,CatalogInventoryLookup c,WarehouseAvailability w,JdbcTemplate j,ApplicationEventPublisher e,TraceabilityService t){auth=a;audit=au;catalog=c;warehouse=w;jdbc=j;events=e;trace=t;}
 @Transactional AdjustmentResult adjust(String key,Adjustment command){var actor=auth.require(Permission.INVENTORY_ADJUST);String idempotency=key==null?null:key.trim();if(idempotency==null||idempotency.isEmpty()||idempotency.length()>128)throw new InventoryException("IDEMPOTENCY_KEY_REQUIRED","A valid Idempotency-Key is required");BigDecimal delta=quantity(command.quantityDelta);Reason reason=reason(command.reason);if(reason==Reason.OTHER&&(command.note==null||command.note.isBlank()))throw new InventoryException("INVALID_ADJUSTMENT_REASON","OTHER requires a note");String fingerprint=fingerprint(actor.tenantId(),command,delta,reason);lock(actor.tenantId()+":idem:"+idempotency);List<AdjustmentResult> existing=jdbc.query("SELECT m.id,e.quantity_delta,e.unit_code,b.on_hand_quantity,m.recorded_at FROM inventory_movements m JOIN inventory_ledger_entries e ON e.tenant_id=m.tenant_id AND e.movement_id=m.id JOIN inventory_balances b ON b.tenant_id=e.tenant_id AND b.variant_id=e.variant_id AND b.warehouse_id=e.warehouse_id AND b.location_id=e.location_id AND b.lot_id IS NOT DISTINCT FROM e.lot_id AND b.serial_id IS NOT DISTINCT FROM e.serial_id WHERE m.tenant_id=? AND m.idempotency_key=?",this::adjustmentRow,actor.tenantId(),idempotency);if(!existing.isEmpty()){String stored=jdbc.queryForObject("SELECT request_fingerprint FROM inventory_movements WHERE tenant_id=? AND idempotency_key=?",String.class,actor.tenantId(),idempotency);if(!fingerprint.equals(stored))throw new InventoryException("IDEMPOTENCY_KEY_REUSED","Idempotency key was used for a different request");return existing.getFirst();}
  var variant=catalog.findInventoryVariant(actor.tenantId(),command.variantId).orElseThrow(()->new InventoryException("VARIANT_NOT_INVENTORY_ELIGIBLE","Variant is inaccessible or missing"));if(variant.status().equals("ARCHIVED")||variant.status().equals("DRAFT"))throw new InventoryException("VARIANT_NOT_INVENTORY_ELIGIBLE","Variant is not inventory eligible");if(variant.discrete()&&delta.stripTrailingZeros().scale()>0)throw new InventoryException("INVALID_INVENTORY_QUANTITY","Base unit requires an integral quantity");var dimension=trace.resolve(actor.tenantId(),command.variantId,command.lotId,command.serialId,variant.trackingMode());if(command.serialId!=null&&delta.abs().compareTo(BigDecimal.ONE)!=0)throw new InventoryException("INVALID_SERIAL_QUANTITY","Serialized adjustment must be +1 or -1");warehouse.findUsableLocation(actor.tenantId(),command.warehouseId,command.locationId).orElseThrow(()->new InventoryException("LOCATION_NOT_INVENTORY_ELIGIBLE","Warehouse/location is inaccessible, mismatched, inactive or blocked"));
  if(command.serialId!=null)lock(actor.tenantId()+":serial:"+command.serialId);lock(actor.tenantId()+":"+command.variantId+":"+command.warehouseId+":"+command.locationId+":"+dimension.lotId()+":"+dimension.serialId());if(command.serialId!=null){BigDecimal global=jdbc.queryForObject("SELECT COALESCE(sum(on_hand_quantity),0) FROM inventory_balances WHERE tenant_id=? AND serial_id=?",BigDecimal.class,actor.tenantId(),command.serialId);if(delta.signum()>0&&global.signum()>0)throw new InventoryException("SERIAL_ALREADY_ON_HAND","Serial is already physically on hand");}Instant now=Instant.now();jdbc.update("INSERT INTO inventory_balances(id,tenant_id,variant_id,warehouse_id,location_id,on_hand_quantity,unit_code,updated_at,version,lot_id,serial_id)VALUES (?,?,?,?,?,0,?,?,0,?,?) ON CONFLICT DO NOTHING",UUID.randomUUID(),actor.tenantId(),command.variantId,command.warehouseId,command.locationId,variant.baseUnit(),Timestamp.from(now),dimension.lotId(),dimension.serialId());List<BigDecimal> balances=jdbc.query("UPDATE inventory_balances SET on_hand_quantity=on_hand_quantity+?,updated_at=?,version=version+1 WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=? AND lot_id IS NOT DISTINCT FROM ? AND serial_id IS NOT DISTINCT FROM ? AND on_hand_quantity+?>=0 RETURNING on_hand_quantity",(rs,n)->rs.getBigDecimal(1),delta,Timestamp.from(now),actor.tenantId(),command.variantId,command.warehouseId,command.locationId,dimension.lotId(),dimension.serialId(),delta);if(balances.isEmpty())throw new InventoryException(command.serialId!=null?"SERIAL_NOT_AT_LOCATION":"INSUFFICIENT_ON_HAND",command.serialId!=null?"Serial is not at this location":"Adjustment would make on-hand inventory negative");
  UUID movement=UUID.randomUUID();String type=reason==Reason.INITIAL_LOAD?"OPENING_BALANCE":"MANUAL_ADJUSTMENT";jdbc.update("INSERT INTO inventory_movements(id,tenant_id,movement_type,idempotency_key,request_fingerprint,reason_code,note,actor_subject,correlation_id,occurred_at,recorded_at)VALUES (?,?,?,?,?,?,?,?,?,?,?)",movement,actor.tenantId(),type,idempotency,fingerprint,reason.name(),trim(command.note,500),actor.subject(),MDC.get("correlationId"),Timestamp.from(now),Timestamp.from(now));jdbc.update("INSERT INTO inventory_ledger_entries(id,tenant_id,movement_id,sequence,variant_id,warehouse_id,location_id,quantity_delta,unit_code,occurred_at,recorded_at,lot_id,serial_id)VALUES (?,?,?,0,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),actor.tenantId(),movement,command.variantId,command.warehouseId,command.locationId,delta,variant.baseUnit(),Timestamp.from(now),Timestamp.from(now),dimension.lotId(),dimension.serialId());audit.record(actor,"INVENTORY_ADJUSTMENT_POSTED","inventory-movement",movement.toString());events.publishEvent(new InventoryEvents.InventoryMovementPosted(actor.tenantId(),movement,command.variantId,command.warehouseId,command.locationId,dimension.lotId(),dimension.serialId(),delta));return new AdjustmentResult(movement,delta,variant.baseUnit(),balances.getFirst(),now);}
 @Transactional(readOnly=true)List<BalanceView>balances(UUID variant,UUID wh,UUID loc,Boolean positive,int page,int size,String sort){var a=auth.require(Permission.INVENTORY_READ);Page p=page(page,size,sort,Map.of("updatedAt","updated_at","onHand","on_hand_quantity","variantId","variant_id"),"updated_at DESC");String sql="SELECT id,variant_id,warehouse_id,location_id,on_hand_quantity,unit_code,updated_at,version,lot_id,serial_id FROM inventory_balances WHERE tenant_id=? AND (?::uuid IS NULL OR variant_id=?::uuid) AND (?::uuid IS NULL OR warehouse_id=?::uuid) AND (?::uuid IS NULL OR location_id=?::uuid) AND (?::boolean IS NULL OR NOT ?::boolean OR on_hand_quantity>0) ORDER BY "+p.order+" OFFSET ? LIMIT ?";return jdbc.query(sql,this::balanceRow,a.tenantId(),variant,variant,wh,wh,loc,loc,positive,positive,p.offset(),p.size);}
 @Transactional(readOnly=true)List<LedgerView>ledger(UUID variant,UUID wh,UUID loc,UUID lot,UUID serial,String type,Instant from,Instant to,int page,int size,String sort){var a=auth.require(Permission.INVENTORY_LEDGER_READ);Page p=page(page,size,sort,Map.of("occurredAt","e.occurred_at","recordedAt","e.recorded_at"),"e.occurred_at DESC");String sql="SELECT e.id,e.movement_id,e.variant_id,e.warehouse_id,e.location_id,e.quantity_delta,e.unit_code,e.occurred_at,e.recorded_at,m.movement_type,m.reason_code FROM inventory_ledger_entries e JOIN inventory_movements m ON m.tenant_id=e.tenant_id AND m.id=e.movement_id WHERE e.tenant_id=? AND (?::uuid IS NULL OR e.variant_id=?::uuid) AND (?::uuid IS NULL OR e.warehouse_id=?::uuid) AND (?::uuid IS NULL OR e.location_id=?::uuid) AND (?::uuid IS NULL OR e.lot_id=?::uuid) AND (?::uuid IS NULL OR e.serial_id=?::uuid) AND (?::text IS NULL OR m.movement_type=?::text) AND (?::timestamptz IS NULL OR e.occurred_at>=?::timestamptz) AND (?::timestamptz IS NULL OR e.occurred_at<=?::timestamptz) ORDER BY "+p.order+" OFFSET ? LIMIT ?";return jdbc.query(sql,this::ledgerRow,a.tenantId(),variant,variant,wh,wh,loc,loc,lot,lot,serial,serial,type,type,from,from,to,to,p.offset(),p.size);}
 @Transactional(readOnly=true)MovementView movement(UUID id){var a=auth.require(Permission.INVENTORY_LEDGER_READ);List<MovementView> rows=jdbc.query("SELECT id,movement_type,idempotency_key,reason_code,note,actor_subject,correlation_id,occurred_at,recorded_at FROM inventory_movements WHERE tenant_id=? AND id=?",(rs,n)->new MovementView((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getTimestamp(8).toInstant(),rs.getTimestamp(9).toInstant(),jdbc.query("SELECT id,movement_id,variant_id,warehouse_id,location_id,quantity_delta,unit_code,occurred_at,recorded_at,'','' FROM inventory_ledger_entries WHERE tenant_id=? AND movement_id=? ORDER BY sequence",this::ledgerRow,a.tenantId(),id)),a.tenantId(),id);if(rows.isEmpty())throw new InventoryException("INVENTORY_MOVEMENT_NOT_FOUND","Movement not found");return rows.getFirst();}
 public Optional<OnHand>findOnHand(UUID tenantId,UUID variantId,UUID warehouseId,UUID locationId){return jdbc.query("SELECT on_hand_quantity,unit_code FROM inventory_balances WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=?",(rs,n)->new OnHand(rs.getBigDecimal(1),rs.getString(2)),tenantId,variantId,warehouseId,locationId).stream().findFirst();}
 @Transactional(readOnly=true)Reconciliation reconcile(UUID variant,UUID wh,UUID loc){var a=auth.require(Permission.INVENTORY_LEDGER_READ);BigDecimal ledger=jdbc.queryForObject("SELECT COALESCE(sum(quantity_delta),0) FROM inventory_ledger_entries WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=?",BigDecimal.class,a.tenantId(),variant,wh,loc);BigDecimal balance=findOnHand(a.tenantId(),variant,wh,loc).map(OnHand::quantity).orElse(BigDecimal.ZERO);return new Reconciliation(ledger,balance,ledger.compareTo(balance)==0);}
 private void lock(String value){jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,value);}private static BigDecimal quantity(String raw){try{BigDecimal q=new BigDecimal(raw).stripTrailingZeros();if(q.signum()==0||q.scale()>6||q.precision()>19)throw new Exception();return q.setScale(6);}catch(Exception e){throw new InventoryException("INVALID_INVENTORY_QUANTITY","Quantity must be non-zero NUMERIC(19,6)");}}private static Reason reason(String raw){try{return Reason.valueOf(raw);}catch(Exception e){throw new InventoryException("INVALID_ADJUSTMENT_REASON","Unsupported adjustment reason");}}private static String trim(String s,int max){if(s==null)return null;s=s.trim();return s.length()>max?s.substring(0,max):s;}private static String fingerprint(UUID tenant,Adjustment c,BigDecimal q,Reason r){try{String canonical=tenant+"|"+c.variantId+"|"+c.warehouseId+"|"+c.locationId+"|"+c.lotId+"|"+c.serialId+"|"+q.toPlainString()+"|"+r+"|"+String.valueOf(trim(c.note,500));return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static Page page(int page,int size,String sort,Map<String,String> allowed,String fallback){if(page<0||size<1||size>100)throw new InventoryException("INVALID_PAGINATION","page must be non-negative and size between 1 and 100");if(sort==null||sort.isBlank())return new Page(page,size,fallback+", id DESC");String[] v=sort.split(",",-1);if(v.length>2||!allowed.containsKey(v[0])||(v.length==2&&!Set.of("asc","desc").contains(v[1].toLowerCase())))throw new InventoryException("INVALID_SORT","Unsupported inventory sort");return new Page(page,size,allowed.get(v[0])+" "+(v.length==2?v[1]:"asc")+", id ASC");}
 private AdjustmentResult adjustmentRow(ResultSet r,int n)throws SQLException{return new AdjustmentResult((UUID)r.getObject(1),r.getBigDecimal(2),r.getString(3),r.getBigDecimal(4),r.getTimestamp(5).toInstant());}private BalanceView balanceRow(ResultSet r,int n)throws SQLException{return new BalanceView((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(9),(UUID)r.getObject(10),r.getBigDecimal(5),r.getString(6),r.getTimestamp(7).toInstant(),r.getLong(8));}private LedgerView ledgerRow(ResultSet r,int n)throws SQLException{return new LedgerView((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),r.getBigDecimal(6),r.getString(7),r.getTimestamp(8).toInstant(),r.getTimestamp(9).toInstant(),r.getString(10),r.getString(11));}
 enum Reason{INITIAL_LOAD,MANUAL_CORRECTION,FOUND,DAMAGE,OTHER}record Adjustment(UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,String quantityDelta,String reason,String note){}record AdjustmentResult(UUID movementId,BigDecimal quantityDelta,String unitCode,BigDecimal onHand,Instant recordedAt){}record BalanceView(UUID id,UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,BigDecimal onHand,String unitCode,Instant updatedAt,long version){}record LedgerView(UUID id,UUID movementId,UUID variantId,UUID warehouseId,UUID locationId,BigDecimal quantityDelta,String unitCode,Instant occurredAt,Instant recordedAt,String movementType,String reason){}record MovementView(UUID id,String movementType,String idempotencyKey,String reason,String note,String actorSubject,String correlationId,Instant occurredAt,Instant recordedAt,List<LedgerView>entries){}record Reconciliation(BigDecimal ledgerTotal,BigDecimal projectedOnHand,boolean healthy){}private record Page(int number,int size,String order){int offset(){return number*size;}}
}
